static bool parallel_generation_job(size_t worker_index, void *context)
{
    PbnfcParallelGeneration *generation =
        (PbnfcParallelGeneration *)context;
    const PbnfcChartSet *set =
        pbnfc_chart_set_const(generation->chart, generation->position);
    const PbnfcMarkupToken *token = NULL;
    size_t total = generation->end - generation->begin;
    size_t base = total / PBNFC_WORKER_POOL_SIZE;
    size_t remainder = total % PBNFC_WORKER_POOL_SIZE;
    size_t local_begin = generation->begin +
                         worker_index * base +
                         (worker_index < remainder ? worker_index : remainder);
    size_t local_end = local_begin + base +
                       (worker_index < remainder ? 1U : 0U);
    size_t item_index;

    if (set == NULL || local_begin > local_end || local_end > generation->end) {
        return false;
    }
    if (generation->scanning) {
        if (generation->position >= generation->token_count) {
            return false;
        }
        token = &generation->tokens[generation->position];
    }
    for (item_index = local_begin; item_index < local_end; ++item_index) {
        const PbnfcChartItem *item = pbnfc_chart_set_at(set, item_index);
        const PbnfcGrammarProduction *production;
        const PbnfcGrammarAlternative *alternative;
        const PbnfcGrammarSymbol *symbol;

        if (item == NULL || item->production >= generation->grammar->production_count) {
            return false;
        }
        production = &generation->grammar->productions[item->production];
        if (item->alternative >= production->alternative_count) {
            return false;
        }
        alternative = &production->alternatives[item->alternative];
        if (item->dot > alternative->symbol_count) {
            return false;
        }
        ++generation->tasks[worker_index];
        if (generation->scanning) {
            ++generation->scan_tasks[worker_index];
        }
        if (generation->scanning) {
            PbnfcChartItem candidate;

            if (item->dot == alternative->symbol_count) {
                continue;
            }
            symbol = &alternative->symbols[item->dot];
            if ((symbol->kind != PBNFC_GRAMMAR_SYMBOL_TERMINAL &&
                 symbol->kind != PBNFC_GRAMMAR_SYMBOL_TOKEN_REFERENCE) ||
                !text_matches(symbol, token)) {
                continue;
            }
            candidate = pbnfc_chart_item_make(item->production,
                                              item->alternative,
                                              item->dot + 1U,
                                              item->origin,
                                              generation->position + 1U);
            if (!candidate_append(&generation->candidates[worker_index],
                                  &candidate)) {
                return false;
            }
        } else if (item->dot == alternative->symbol_count) {
            if (!parallel_completion_candidates(generation,
                                                worker_index,
                                                item)) {
                return false;
            }
        } else {
            symbol = &alternative->symbols[item->dot];
            if (symbol->kind == PBNFC_GRAMMAR_SYMBOL_NONTERMINAL &&
                !parallel_prediction_candidates(generation,
                                                worker_index,
                                                item,
                                                symbol)) {
                return false;
            }
        }
    }
    return true;
}

static int chart_item_compare(const void *left_argument,
                              const void *right_argument)
{
    const PbnfcChartItem *left = (const PbnfcChartItem *)left_argument;
    const PbnfcChartItem *right = (const PbnfcChartItem *)right_argument;

#define PBNFC_COMPARE_FIELD(field) \
    if (left->field < right->field) { \
        return -1; \
    } \
    if (left->field > right->field) { \
        return 1; \
    }
    PBNFC_COMPARE_FIELD(production)
    PBNFC_COMPARE_FIELD(alternative)
    PBNFC_COMPARE_FIELD(dot)
    PBNFC_COMPARE_FIELD(origin)
    PBNFC_COMPARE_FIELD(position)
#undef PBNFC_COMPARE_FIELD
    return 0;
}

static bool merge_parallel_candidates(PbnfcParallelGeneration *generation)
{
    PbnfcChartItem *merged = NULL;
    size_t total = 0U;
    size_t unique_count = 0U;
    size_t worker_index;
    size_t item_index;
    size_t offset = 0U;

    for (worker_index = 0U;
         worker_index < PBNFC_WORKER_POOL_SIZE;
         ++worker_index) {
        if (total > SIZE_MAX - generation->candidates[worker_index].count) {
            return false;
        }
        total += generation->candidates[worker_index].count;
    }
    if (total != 0U) {
        if (total > SIZE_MAX / sizeof(*merged)) {
            return false;
        }
        merged = (PbnfcChartItem *)malloc(total * sizeof(*merged));
        if (merged == NULL) {
            return false;
        }
    }
    for (worker_index = 0U;
         worker_index < PBNFC_WORKER_POOL_SIZE;
         ++worker_index) {
        for (item_index = 0U;
             item_index < generation->candidates[worker_index].count;
             ++item_index) {
            merged[offset++] =
                generation->candidates[worker_index].items[item_index];
        }
    }
    if (total != 0U) {
        qsort(merged, total, sizeof(*merged), chart_item_compare);
    }

    /*
     * The comparator orders every field participating in chart-item identity,
     * so equal candidates are adjacent. Compact them before touching the
     * shared chart; this keeps the coordinator's merge boundary explicit and
     * makes insertion order independent of worker completion order.
     */
    for (item_index = 0U; item_index < total; ++item_index) {
        if (unique_count == 0U ||
            !pbnfc_chart_item_equal(&merged[item_index],
                                    &merged[unique_count - 1U])) {
            merged[unique_count++] = merged[item_index];
        }
    }
    for (item_index = 0U; item_index < unique_count; ++item_index) {
        if (pbnfc_chart_insert(generation->chart, &merged[item_index]) ==
            PBNFC_CHART_INSERT_ERROR) {
            free(merged);
            return false;
        }
    }
    free(merged);
    return true;
}

static bool run_parallel_generation(PbnfcWorkerPool *pool,
                                    PbnfcParallelGeneration *generation,
                                    PbnfcRecognitionStats *stats)
{
    bool succeeded;
    size_t worker_index;

    candidate_vectors_reset(generation->candidates);
    succeeded = pbnfc_worker_pool_run(pool,
                                      parallel_generation_job,
                                      generation);
    if (!succeeded || !merge_parallel_candidates(generation)) {
        return false;
    }
    if (stats != NULL) {
        ++stats->rounds;
    }
    for (worker_index = 0U;
         worker_index < PBNFC_WORKER_POOL_SIZE;
         ++worker_index) {
        if (stats != NULL) {
            stats->tasks[worker_index] += generation->tasks[worker_index];
            if (generation->scanning) {
                stats->scan_tasks[worker_index] +=
                    generation->scan_tasks[worker_index];
            }
        }
        generation->tasks[worker_index] = 0U;
        generation->scan_tasks[worker_index] = 0U;
    }
    return true;
}

static bool close_parallel_position(PbnfcWorkerPool *pool,
                                    PbnfcParallelGeneration *generation,
                                    size_t position,
                                    PbnfcRecognitionStats *stats)
{
    size_t cursor = 0U;

    generation->position = position;
    generation->scanning = false;
    while (cursor < pbnfc_chart_set_size(
                        pbnfc_chart_set_const(generation->chart, position))) {
        generation->begin = cursor;
        generation->end = pbnfc_chart_set_size(
            pbnfc_chart_set_const(generation->chart, position));
        if (!run_parallel_generation(pool, generation, stats)) {
            return false;
        }
        cursor = generation->end;
    }
    return true;
}

static bool scan_parallel_position(PbnfcWorkerPool *pool,
                                   PbnfcParallelGeneration *generation,
                                   size_t position,
                                   PbnfcRecognitionStats *stats)
{
    generation->position = position;
    generation->begin = 0U;
    generation->end = pbnfc_chart_set_size(
        pbnfc_chart_set_const(generation->chart, position));
    generation->scanning = true;
    return run_parallel_generation(pool, generation, stats);
}

PbnfcRecognitionResult pbnfc_recognize_parallel(
    const PbnfcGrammar *grammar,
    const PbnfcMarkupToken *tokens,
    size_t token_count,
    const char *start_name,
    PbnfcRecognitionStats *stats)
{
    return pbnfc_recognize_parallel_with_diagnostics(grammar,
                                                     tokens,
                                                     token_count,
                                                     start_name,
                                                     NULL,
                                                     stats);
}

PbnfcRecognitionResult pbnfc_recognize_parallel_with_diagnostics(
    const PbnfcGrammar *grammar,
    const PbnfcMarkupToken *tokens,
    size_t token_count,
    const char *start_name,
    const PbnfcDiagnosticContext *diagnostics,
    PbnfcRecognitionStats *stats)
{
    PbnfcChart chart;
    PbnfcWorkerPool pool = {0};
    PbnfcParallelGeneration generation = {0};
    size_t start_production;
    size_t alternative;
    size_t position;
    size_t rejection_position = 0U;
    const PbnfcChartSet *rejection_set = NULL;
    const char *effective_start;
    char *expected = NULL;
    PbnfcLocation rejection_location;
    PbnfcRecognitionResult result = PBNFC_RECOGNITION_ERROR;

    if (stats != NULL) {
        (void)memset(stats, 0, sizeof(*stats));
    }
    if (grammar == NULL || (tokens == NULL && token_count != 0U) ||
        grammar->start_count == 0U) {
        return PBNFC_RECOGNITION_ERROR;
    }
    effective_start = start_name == NULL ? grammar->start_name : start_name;
    if (effective_start == NULL ||
        !production_index(grammar, effective_start, &start_production) ||
        token_count == SIZE_MAX || !pbnfc_chart_init(&chart, token_count + 1U)) {
        return PBNFC_RECOGNITION_ERROR;
    }
    if (!pbnfc_worker_pool_init(&pool)) {
        pbnfc_chart_free(&chart);
        return PBNFC_RECOGNITION_ERROR;
    }
    if (stats != NULL) {
        stats->workers = pbnfc_worker_pool_worker_count(&pool);
        stats->active_workers = stats->workers;
    }
    generation.chart = &chart;
    generation.grammar = grammar;
    generation.tokens = tokens;
    generation.token_count = token_count;
    for (alternative = 0U;
         alternative < grammar->productions[start_production].alternative_count;
         ++alternative) {
        if (!insert_item(&chart, start_production, alternative, 0U, 0U, 0U)) {
            goto cleanup;
        }
    }
    for (position = 0U; position <= token_count; ++position) {
        if (!close_parallel_position(&pool,
                                     &generation,
                                     position,
                                     stats)) {
            goto cleanup;
        }
        if (position < token_count) {
            if (!scan_parallel_position(&pool,
                                        &generation,
                                        position,
                                        stats)) {
                goto cleanup;
            }
            if (pbnfc_chart_set_size(pbnfc_chart_set_const(&chart,
                                                           position + 1U)) ==
                0U) {
                rejection_position = position;
                rejection_set = pbnfc_chart_set_const(&chart, position);
                break;
            }
        }
    }
    if (has_accepting_item(&chart,
                           grammar,
                           start_production,
                           token_count)) {
        result = PBNFC_RECOGNITION_ACCEPTED;
        goto cleanup;
    }
    if (rejection_set == NULL) {
        rejection_position = token_count;
        rejection_set = pbnfc_chart_set_const(&chart, token_count);
    }
    expected = expected_detail(rejection_set, grammar);
    if (expected == NULL) {
        goto cleanup;
    }
    rejection_location = rejection_position < token_count
                             ? tokens[rejection_position].location
                             : eof_location(tokens, token_count);
    if (diagnostics != NULL) {
        (void)pbnfc_rejection_emit(diagnostics,
                                   expected,
                                   &rejection_location);
    }
    result = PBNFC_RECOGNITION_REJECTED;

cleanup:
    free(expected);
    candidate_vectors_free(generation.candidates);
    pbnfc_worker_pool_free(&pool);
    pbnfc_chart_free(&chart);
    return result;
}

#include "markup_lexer.h"

static bool is_layout_space(unsigned char character)
{
    return character == (unsigned char)' ' ||
           character == (unsigned char)'\t' ||
           character == (unsigned char)'\v' ||
           character == (unsigned char)'\f' ||
           character == (unsigned char)'\r' ||
           character == (unsigned char)'\n';
}

static bool is_identifier_start(unsigned char character)
{
    return (character >= (unsigned char)'A' &&
            character <= (unsigned char)'Z') ||
           (character >= (unsigned char)'a' &&
            character <= (unsigned char)'z') ||
           character == (unsigned char)'_' ||
           character == (unsigned char)':';
}

static bool is_identifier_part(unsigned char character)
{
    return is_identifier_start(character) ||
           (character >= (unsigned char)'0' &&
            character <= (unsigned char)'9') ||
           character == (unsigned char)'.' ||
           character == (unsigned char)'-';
}

static unsigned char current_character(const PbnfcMarkupLexer *lexer)
{
    return (unsigned char)lexer->source[lexer->offset];
}

static void advance_one(PbnfcMarkupLexer *lexer)
{
    unsigned char character = current_character(lexer);

    ++lexer->offset;
    if (character == (unsigned char)'\n') {
        ++lexer->line;
        lexer->column = 1U;
    } else {
        ++lexer->column;
    }
}

static void skip_layout_space(PbnfcMarkupLexer *lexer)
{
    while (lexer->offset < lexer->length &&
           is_layout_space(current_character(lexer))) {
        advance_one(lexer);
    }
}

static bool text_has_nonspace(const PbnfcMarkupLexer *lexer, size_t start)
{
    size_t offset = start;

    while (offset < lexer->offset) {
        if (!is_layout_space((unsigned char)lexer->source[offset])) {
            return true;
        }
        ++offset;
    }
    return false;
}

static void set_token(PbnfcMarkupToken *token,
                      PbnfcMarkupTokenKind kind,
                      PbnfcLocation location,
                      const char *text,
                      size_t length)
{
    token->kind = kind;
    token->location = location;
    token->text = text;
    token->length = length;
}

static bool emit_error(PbnfcMarkupLexer *lexer,
                       const PbnfcLocation *location,
                       const char *detail)
{
    lexer->failed = true;
    if (lexer->diagnostics != NULL) {
        (void)pbnfc_diagnostic_emit(lexer->diagnostics, detail, location);
    }
    return false;
}

static bool fail_at_current(PbnfcMarkupLexer *lexer, const char *detail)
{
    PbnfcLocation location;

    location.byte_offset = lexer->offset;
    location.line = lexer->line;
    location.column = lexer->column;
    return emit_error(lexer, &location, detail);
}

static bool tag_state_allows_end(PbnfcMarkupTagState state)
{
    return state == PBNFC_MARKUP_TAG_AFTER_NAME ||
           state == PBNFC_MARKUP_TAG_AFTER_VALUE ||
           state == PBNFC_MARKUP_TAG_AFTER_CLOSE_NAME ||
           state == PBNFC_MARKUP_TAG_EXPECT_SELF_CLOSE_END;
}

static bool tag_state_allows_slash(PbnfcMarkupTagState state)
{
    return state == PBNFC_MARKUP_TAG_EXPECT_NAME ||
           state == PBNFC_MARKUP_TAG_AFTER_NAME ||
           state == PBNFC_MARKUP_TAG_AFTER_VALUE;
}

static bool tag_state_allows_identifier(PbnfcMarkupTagState state)
{
    return state == PBNFC_MARKUP_TAG_EXPECT_NAME ||
           state == PBNFC_MARKUP_TAG_EXPECT_CLOSE_NAME ||
           state == PBNFC_MARKUP_TAG_AFTER_NAME ||
           state == PBNFC_MARKUP_TAG_EXPECT_VALUE ||
           state == PBNFC_MARKUP_TAG_AFTER_VALUE;
}

static bool read_string(PbnfcMarkupLexer *lexer,
                        PbnfcMarkupToken *token,
                        PbnfcLocation location)
{
    const size_t start = lexer->offset;
    const unsigned char quote = current_character(lexer);

    advance_one(lexer);
    while (lexer->offset < lexer->length) {
        unsigned char character = current_character(lexer);

        if (character >= 0x80U) {
            return fail_at_current(lexer, "invalid markup byte");
        }
        if (character == (unsigned char)'\\') {
            advance_one(lexer);
            if (lexer->offset == lexer->length) {
                return emit_error(lexer,
                                  &location,
                                  "unterminated markup quoted value");
            }
            character = current_character(lexer);
            if (character != quote && character != (unsigned char)'\\') {
                return emit_error(lexer,
                                  &location,
                                  "invalid markup value escape");
            }
            advance_one(lexer);
            continue;
        }
        if (character == quote) {
            advance_one(lexer);
            lexer->tag_state = PBNFC_MARKUP_TAG_AFTER_VALUE;
            set_token(token,
                      PBNFC_MARKUP_TOKEN_STRING,
                      location,
                      lexer->source + start,
                      lexer->offset - start);
            return true;
        }
        advance_one(lexer);
    }

    return emit_error(lexer,
                      &location,
                      "unterminated markup quoted value");
}

void pbnfc_markup_lexer_init(PbnfcMarkupLexer *lexer,
                             const char *source,
                             size_t length,
                             const PbnfcDiagnosticContext *diagnostics)
{
    if (lexer == NULL) {
        return;
    }
    lexer->source = source;
    lexer->length = length;
    lexer->offset = 0U;
    lexer->line = 1U;
    lexer->column = 1U;
    lexer->in_tag = false;
    lexer->tag_state = PBNFC_MARKUP_TAG_EXPECT_NAME;
    lexer->diagnostics = diagnostics;
    lexer->failed = false;
}

bool pbnfc_markup_lexer_next(PbnfcMarkupLexer *lexer,
                             PbnfcMarkupToken *token)
{
    PbnfcLocation location;
    size_t start;
    unsigned char character;

    if (lexer == NULL || token == NULL || lexer->failed) {
        return false;
    }
    if (lexer->source == NULL && lexer->length != 0U) {
        return fail_at_current(lexer, "markup source is unavailable");
    }

    if (lexer->in_tag) {
        skip_layout_space(lexer);
    } else {
        for (;;) {
            start = lexer->offset;
            location.byte_offset = start;
            location.line = lexer->line;
            location.column = lexer->column;

            while (lexer->offset < lexer->length &&
                   current_character(lexer) != (unsigned char)'<') {
                advance_one(lexer);
            }
            if (lexer->offset != start) {
                if (text_has_nonspace(lexer, start)) {
                    set_token(token,
                              PBNFC_MARKUP_TOKEN_TEXT,
                              location,
                              lexer->source + start,
                              lexer->offset - start);
                    return true;
                }
                continue;
            }
            break;
        }
    }

    if (lexer->offset == lexer->length) {
        if (lexer->in_tag) {
            return fail_at_current(lexer, "unterminated markup tag");
        }
        location.byte_offset = lexer->offset;
        location.line = lexer->line;
        location.column = lexer->column;
        set_token(token,
                  PBNFC_MARKUP_TOKEN_EOF,
                  location,
                  lexer->source == NULL ? NULL : lexer->source + lexer->offset,
                  0U);
        return true;
    }

    start = lexer->offset;
    location.byte_offset = start;
    location.line = lexer->line;
    location.column = lexer->column;
    character = current_character(lexer);

    if (!lexer->in_tag) {
        if (character != (unsigned char)'<') {
            return fail_at_current(lexer, "invalid markup byte");
        }
        advance_one(lexer);
        lexer->in_tag = true;
        lexer->tag_state = PBNFC_MARKUP_TAG_EXPECT_NAME;
        set_token(token,
                  PBNFC_MARKUP_TOKEN_LESS_THAN,
                  location,
                  lexer->source + start,
                  1U);
        return true;
    }

    if (character >= 0x80U) {
        return fail_at_current(lexer, "invalid markup byte");
    }
    if (character == (unsigned char)'<') {
        return fail_at_current(lexer, "invalid markup tag transition");
    }
    if (character == (unsigned char)'>') {
        if (!tag_state_allows_end(lexer->tag_state)) {
            return fail_at_current(lexer, "invalid markup tag transition");
        }
        advance_one(lexer);
        lexer->in_tag = false;
        set_token(token,
                  PBNFC_MARKUP_TOKEN_GREATER_THAN,
                  location,
                  lexer->source + start,
                  1U);
        return true;
    }
    if (character == (unsigned char)'/') {
        if (!tag_state_allows_slash(lexer->tag_state)) {
            return fail_at_current(lexer, "invalid markup tag transition");
        }
        advance_one(lexer);
        if (lexer->tag_state == PBNFC_MARKUP_TAG_EXPECT_NAME) {
            lexer->tag_state = PBNFC_MARKUP_TAG_EXPECT_CLOSE_NAME;
        } else {
            lexer->tag_state = PBNFC_MARKUP_TAG_EXPECT_SELF_CLOSE_END;
        }
        set_token(token,
                  PBNFC_MARKUP_TOKEN_SLASH,
                  location,
                  lexer->source + start,
                  1U);
        return true;
    }
    if (character == (unsigned char)'=') {
        if (lexer->tag_state != PBNFC_MARKUP_TAG_EXPECT_EQUALS) {
            return fail_at_current(lexer, "invalid markup tag transition");
        }
        advance_one(lexer);
        lexer->tag_state = PBNFC_MARKUP_TAG_EXPECT_VALUE;
        set_token(token,
                  PBNFC_MARKUP_TOKEN_EQUALS,
                  location,
                  lexer->source + start,
                  1U);
        return true;
    }
    if (character == (unsigned char)'\'' ||
        character == (unsigned char)'"') {
        if (lexer->tag_state != PBNFC_MARKUP_TAG_EXPECT_VALUE) {
            return fail_at_current(lexer, "invalid markup tag transition");
        }
        return read_string(lexer, token, location);
    }
    if (is_identifier_start(character)) {
        if (!tag_state_allows_identifier(lexer->tag_state)) {
            return fail_at_current(lexer, "invalid markup tag transition");
        }
        do {
            advance_one(lexer);
        } while (lexer->offset < lexer->length &&
                 is_identifier_part(current_character(lexer)));
        if (lexer->tag_state == PBNFC_MARKUP_TAG_EXPECT_NAME) {
            lexer->tag_state = PBNFC_MARKUP_TAG_AFTER_NAME;
        } else if (lexer->tag_state == PBNFC_MARKUP_TAG_EXPECT_CLOSE_NAME) {
            lexer->tag_state = PBNFC_MARKUP_TAG_AFTER_CLOSE_NAME;
        } else if (lexer->tag_state == PBNFC_MARKUP_TAG_EXPECT_VALUE) {
            lexer->tag_state = PBNFC_MARKUP_TAG_AFTER_VALUE;
        } else {
            lexer->tag_state = PBNFC_MARKUP_TAG_EXPECT_EQUALS;
        }
        set_token(token,
                  PBNFC_MARKUP_TOKEN_IDENT,
                  location,
                  lexer->source + start,
                  lexer->offset - start);
        return true;
    }

    return fail_at_current(lexer, "invalid markup punctuation");
}

bool pbnfc_markup_lexer_failed(const PbnfcMarkupLexer *lexer)
{
    return lexer != NULL && lexer->failed;
}

const char *pbnfc_markup_token_kind_name(PbnfcMarkupTokenKind kind)
{
    switch (kind) {
    case PBNFC_MARKUP_TOKEN_EOF:
        return "EOF";
    case PBNFC_MARKUP_TOKEN_LESS_THAN:
        return "<";
    case PBNFC_MARKUP_TOKEN_GREATER_THAN:
        return ">";
    case PBNFC_MARKUP_TOKEN_SLASH:
        return "/";
    case PBNFC_MARKUP_TOKEN_EQUALS:
        return "=";
    case PBNFC_MARKUP_TOKEN_IDENT:
        return "IDENT";
    case PBNFC_MARKUP_TOKEN_STRING:
        return "STRING";
    case PBNFC_MARKUP_TOKEN_TEXT:
        return "TEXT";
    }
    return "unknown";
}
#ifndef PBNFC_MARKUP_LEXER_H
#define PBNFC_MARKUP_LEXER_H

#include "diagnostics.h"

#include <stdbool.h>
#include <stddef.h>

typedef enum {
    PBNFC_MARKUP_TOKEN_EOF = 0,
    PBNFC_MARKUP_TOKEN_LESS_THAN,
    PBNFC_MARKUP_TOKEN_GREATER_THAN,
    PBNFC_MARKUP_TOKEN_SLASH,
    PBNFC_MARKUP_TOKEN_EQUALS,
    PBNFC_MARKUP_TOKEN_IDENT,
    PBNFC_MARKUP_TOKEN_STRING,
    PBNFC_MARKUP_TOKEN_TEXT,

    /* Short names keep punctuation tokens convenient for scanner clients. */
    PBNFC_MARKUP_TOKEN_LT = PBNFC_MARKUP_TOKEN_LESS_THAN,
    PBNFC_MARKUP_TOKEN_GT = PBNFC_MARKUP_TOKEN_GREATER_THAN,
    PBNFC_MARKUP_TOKEN_EQUAL = PBNFC_MARKUP_TOKEN_EQUALS,
    PBNFC_MARKUP_TOKEN_IDENTIFIER = PBNFC_MARKUP_TOKEN_IDENT
} PbnfcMarkupTokenKind;

/* A token is a non-owning view into the source supplied to the lexer. */
typedef struct {
    PbnfcMarkupTokenKind kind;
    PbnfcLocation location;
    const char *text;
    size_t length;
} PbnfcMarkupToken;

typedef enum {
    PBNFC_MARKUP_TAG_EXPECT_NAME = 0,
    PBNFC_MARKUP_TAG_EXPECT_CLOSE_NAME,
    PBNFC_MARKUP_TAG_AFTER_NAME,
    PBNFC_MARKUP_TAG_EXPECT_EQUALS,
    PBNFC_MARKUP_TAG_EXPECT_VALUE,
    PBNFC_MARKUP_TAG_AFTER_VALUE,
    PBNFC_MARKUP_TAG_EXPECT_SELF_CLOSE_END,
    PBNFC_MARKUP_TAG_AFTER_CLOSE_NAME
} PbnfcMarkupTagState;

typedef struct {
    const char *source;
    size_t length;
    size_t offset;
    size_t line;
    size_t column;
    bool in_tag;
    PbnfcMarkupTagState tag_state;
    const PbnfcDiagnosticContext *diagnostics;
    bool failed;
} PbnfcMarkupLexer;

/* Initialize a markup scanner. The source buffer remains caller-owned. */
void pbnfc_markup_lexer_init(PbnfcMarkupLexer *lexer,
                             const char *source,
                             size_t length,
                             const PbnfcDiagnosticContext *diagnostics);

/* Returns true for each token, including EOF, and false after malformed input. */
bool pbnfc_markup_lexer_next(PbnfcMarkupLexer *lexer,
                             PbnfcMarkupToken *token);

bool pbnfc_markup_lexer_failed(const PbnfcMarkupLexer *lexer);

const char *pbnfc_markup_token_kind_name(PbnfcMarkupTokenKind kind);

#endif
